-- NPHIES Invoices (Sehati platform fees) — read-only SQL pack. Run with cure_run_query.
-- 1) Riyadh ledger: every Sehati fee line, posted AND open vouchers (status P/O), plus every line on the Sehati supplier sub-account 2122001 · S0471 whatever its narration. Packed 20 lines per row.
SELECT 'B'||FLOOR((RN-1)/20) B, LISTAGG(S, '~') WITHIN GROUP (ORDER BY RN) X FROM (SELECT ROW_NUMBER() OVER (ORDER BY VM_DATE, VOUCHER_NO, ACCOUNT_NO, DR_AMOUNT, CR_AMOUNT) RN, TO_CHAR(VM_DATE,'YYYY-MM-DD')||'|'||VOUCHER_NO||'|'||ACCOUNT_NO||'|'||ROUND(DR_AMOUNT-CR_AMOUNT,2)||'|'||STATUS||'|'||NVL(SUB_ACCOUNT_NO,'-')||'|'||REPLACE(REPLACE(REPLACE(REPLACE(SUBSTR(DESCRIPTION,1,170),CHR(10),' '),CHR(13),' '),'|','/'),'~','-') S FROM EXSYS.GL_TRANSACTIONS_DETAILS WHERE STATUS IN ('P','O') AND VM_DATE >= DATE '2023-01-01' AND ((ACCOUNT_NO IN ('3320004','3140001','1263000','2122001') AND (DESCRIPTION LIKE '%نفيس%' OR DESCRIPTION LIKE '%منصة نفس%') AND DESCRIPTION NOT LIKE '%ديج%' AND DESCRIPTION NOT LIKE '%عمول%' AND DESCRIPTION NOT LIKE '%رسوم تحويل%' AND DESCRIPTION NOT LIKE '%رسوم  تحويل%' AND DESCRIPTION NOT LIKE '%رسوم حوالة%' AND DESCRIPTION NOT LIKE '%رسوم  حوالة%') OR (ACCOUNT_NO='2122001' AND SUB_ACCOUNT_NO='S0471')) AND ABS(DR_AMOUNT-CR_AMOUNT)>2) GROUP BY FLOOR((RN-1)/20) ORDER BY 1;
-- 2) Rafha: claims sent to NPHIES by month, type, outcome
SELECT TO_CHAR(CREATION_DATE,'YYYY-MM') M, MESSAGE_EVENT_TYPE T, NVL(OUTCOME,'none') O, COUNT(*) N, ROUND(SUM(TOTAL_GROSS_AMOUNT),2) G, ROUND(SUM(TOTAL_COMPANY_SHARE_AMOUNT),2) CO, ROUND(SUM(TOTAL_COMPANY_NET_AMOUNT),2) NET FROM HS_NPHIES_CLAIM_REQUEST WHERE CREATION_DATE >= DATE '2025-01-01' GROUP BY TO_CHAR(CREATION_DATE,'YYYY-MM'), MESSAGE_EVENT_TYPE, NVL(OUTCOME,'none') ORDER BY 1,2,3;
-- 3) Rafha: other NPHIES messages by month
SELECT 'API' T, TO_CHAR(API_DATE,'YYYY-MM') M, MESSAGE_EVENT E, COUNT(*) N FROM HS_NPHIES_API_HISTORY WHERE API_DATE >= DATE '2024-12-01' GROUP BY TO_CHAR(API_DATE,'YYYY-MM'), MESSAGE_EVENT UNION ALL SELECT 'PRE', TO_CHAR(CREATION_DATE,'YYYY-MM'), OUTCOME, COUNT(*) FROM HS_NPHIES_PREAUTH_REQUEST WHERE CREATION_DATE >= DATE '2024-12-01' GROUP BY TO_CHAR(CREATION_DATE,'YYYY-MM'), OUTCOME UNION ALL SELECT 'CLR', TO_CHAR(API_DATE,'YYYY-MM'), 'resp', COUNT(*) FROM HS_NPHIES_CLAIM_RESPONSE_DATA WHERE API_DATE >= DATE '2024-12-01' GROUP BY TO_CHAR(API_DATE,'YYYY-MM') UNION ALL SELECT 'POLL', TO_CHAR(API_DATE,'YYYY-MM'), MESSAGE_EVENT, COUNT(*) FROM HS_NPHIES_POLL_HISTORY WHERE API_DATE >= DATE '2024-12-01' GROUP BY TO_CHAR(API_DATE,'YYYY-MM'), MESSAGE_EVENT UNION ALL SELECT 'COM', TO_CHAR(API_DATE,'YYYY-MM'), 'com', COUNT(*) FROM HS_NPHIES_COMMUNICATION WHERE API_DATE >= DATE '2024-12-01' GROUP BY TO_CHAR(API_DATE,'YYYY-MM') ORDER BY 1,3,2;
-- Refresh: parse_pdfs.py on the computer -> pdf_invoices.json; save results 1-3 as gl_raw.json, act_type.json, act_msg.json; python3 build_nphinv.py; python3 patch.py
-- 4) Rafha: claims by month x insurer sub-account x type x outcome (packed per month) -> ins_raw.json
SELECT M, LISTAGG(S, '~') WITHIN GROUP (ORDER BY S) X FROM (SELECT TO_CHAR(c.CREATION_DATE,'YYYY-MM') M, NVL(ei.ACCOUNT_NO,'-')||'|'||SUBSTR(c.MESSAGE_EVENT_TYPE,1,2)||'|'||CASE WHEN c.OUTCOME='complete' THEN 'A' WHEN c.OUTCOME='error' THEN 'E' ELSE 'O' END||'|'||COUNT(*)||'|'||ROUND(SUM(c.TOTAL_COMPANY_SHARE_AMOUNT),2)||'|'||ROUND(SUM(c.TOTAL_COMPANY_NET_AMOUNT),2) S FROM HS_NPHIES_CLAIM_REQUEST c LEFT JOIN RC_EPISODE_INVOICES ei ON ei.INVOICE_NO=c.EPISODE_INVOICE_NO WHERE c.CREATION_DATE >= DATE '2025-01-01' GROUP BY TO_CHAR(c.CREATION_DATE,'YYYY-MM'), NVL(ei.ACCOUNT_NO,'-'), SUBSTR(c.MESSAGE_EVENT_TYPE,1,2), CASE WHEN c.OUTCOME='complete' THEN 'A' WHEN c.OUTCOME='error' THEN 'E' ELSE 'O' END) GROUP BY M ORDER BY M;
-- 5) Rafha: claim list for one invoice month {M0}..{M1} (run for each month whose PDF is in the folder) -> clm_YYYY-MM.json
SELECT 'C'||FLOOR((RN-1)/30) B, LISTAGG(S, '~') WITHIN GROUP (ORDER BY RN) X FROM (SELECT ROW_NUMBER() OVER (ORDER BY c.CREATION_DATE, c.CLAIM_PK) RN, c.CLAIM_PK||'|'||TO_CHAR(c.CREATION_DATE,'YYYY-MM-DD')||'|'||c.EPISODE_INVOICE_NO||'|'||c.PATIENT_FILE_NO||'|'||SUBSTR(c.MESSAGE_EVENT_TYPE,1,2)||'|'||SUBSTR(NVL(c.OUTCOME,'-'),1,2)||'|'||NVL(ei.ACCOUNT_NO,'-')||'|'||TO_CHAR(ei.INVOICE_START_DATE,'YYYY-MM')||'|'||c.TOTAL_GROSS_AMOUNT||'|'||c.TOTAL_PATIENT_SHARE_AMOUNT||'|'||c.TOTAL_COMPANY_SHARE_AMOUNT||'|'||c.TOTAL_COMPANY_TAX_AMOUNNT||'|'||NVL(c.PREVIOUS_SEND_COUNT,0) S FROM HS_NPHIES_CLAIM_REQUEST c LEFT JOIN RC_EPISODE_INVOICES ei ON ei.INVOICE_NO=c.EPISODE_INVOICE_NO WHERE c.CREATION_DATE >= DATE '{M0}-01' AND c.CREATION_DATE < DATE '{M1}-01') GROUP BY FLOOR((RN-1)/30) ORDER BY 1;
